#!/bin/bash

# Define variables and constants.
RCM_EXTENSION_VERSION=0.1.0-alpha.1

# Usage Functions.
usage() {
    cat << EOF
Usage: rcm devel generate code command [options]

Generate shell command to make shell script of command.

Options:
   --arg=ARG...
        Set the arguments. Multivalue.

Global Options:
   --version
        Print version of this script.
   --help
        Show this help.

EOF
}

# Prevent scripts from being executed directly.
[ -f "${RCM_LIB}/require.sh" ] && source "${RCM_LIB}/require.sh" || { usage >&2; exit 1; }

# Parse arguments. Generated by parse-options.sh.
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help) help=1; shift ;;
        --version) version=1; shift ;;
        --arg=*) arg+=("${1#*=}"); shift ;;
        --arg) if [[ ! $2 == "" && ! $2 =~ (^--$|^-[^-]|^--[^-]) ]]; then arg+=("$2"); shift; fi; shift ;;
        --[^-]*) shift ;;
        *) _new_arguments+=("$1"); shift ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments

# Help and Version.
[ -n "$help" ] && { usage; exit 0; }
[ -n "$version" ] && { e $RCM_EXTENSION_VERSION; x; }

# ------------------------------------------------------------------------------

# Title.
title rcm devel generate code command
____

# Mapping operand to value of options.
chapter Mapping operand as value of options.
if [ -n "$1" ];then
    arg=()
    while [[ $# -gt 0 ]]; do
        code --arg=$1
        arg+=("$1"); shift
    done
fi
____

# Require, validate, and populate value.
chapter Variable dump.
if [[ ${#arg[@]} -eq 0 ]];then
    error "Argument --arg required."; x
fi
declare -i min; min=80
declare -i max; max=100
current_line=
arg_string=
for each in "${arg[@]}";do
    if [ -z "$current_line" ]; then
        current_line="$each"
        arg_string+="$each"
    else
        _current_line="${current_line} ${each}"
        if [ "${#_current_line}" -le $min ];then
            current_line+=" ${each}"
            arg_string+=" ${each}"
        elif [ "${#_current_line}" -le $max ];then
            arg_string+=" ${each}"$'\n'
            current_line=
        else
            arg_string+=$'\n'"${each}"
            current_line="$each"
        fi
    fi
done
code 'arg_string="'"$arg_string"'"'
code 'RCM_LIB="'"$RCM_LIB"'"'
RCM_PREFIX="$RCM_LIB"

# Jika current directory terdapat direktori rcm/install, maka diasumsikan kita
# berada di repository extension nya rcm.
# Contoh: $PWD = /home/ijortengab/github.com/ijortengab/ispconfig-autoinstaller
# Terdapat direktori
# /home/ijortengab/github.com/ijortengab/ispconfig-autoinstaller/rcm/install
# maka variable RCM_PREFIX akan bernilai "$PWD/rcm/install".
git_repo=
if [ -d "$PWD/rcm/install" ];then
    RCM_REPOSITORY="$PWD/rcm/install"
    RCM_PREFIX="$PWD/rcm/install"
    git_repo=1
elif [ -d "$PWD/install/commands" ];then
    # Ini artinya kita berada di repository rcm.
    RCM_REPOSITORY="$PWD/install"
    RCM_PREFIX="$PWD/install"
    git_repo=1
fi
code 'RCM_REPOSITORY="'"$RCM_REPOSITORY"'"'
code 'RCM_PREFIX="'"$RCM_PREFIX"'"'
____

code cd '      ' "$RCM_PREFIX"
echo cd '      ' "$RCM_PREFIX"

RCM_PREFIX=
script=rcm
script_alias=rcm
for each in "${arg[@]}"; do
    RCM_PREFIX+="/commands/$each"
    script_alias+="-${each}"
    script+="-${each}"
    shift
done
script+=.sh
# Trim leading slash.
RCM_PREFIX=${RCM_PREFIX:1}

code mkdir -p '' "$RCM_PREFIX"
echo mkdir -p '' "$RCM_PREFIX"

code touch '   ' "$RCM_PREFIX/${script}"
echo touch '   ' "$RCM_PREFIX/${script}"
code chmod a+x "$RCM_PREFIX/${script}"
echo chmod a+x "$RCM_PREFIX/${script}"
code mkdir -p '' "$RCM_LIB/shortcut-command"
echo mkdir -p '' "$RCM_LIB/shortcut-command"
code cd '      ' "$RCM_LIB/shortcut-command"
echo cd '      ' "$RCM_LIB/shortcut-command"
if [ -n "$git_repo" ];then
    code ln -sf '  ' ${RCM_REPOSITORY}/${RCM_PREFIX}/${script} ${script_alias}
    echo ln -sf '  ' ${RCM_REPOSITORY}/${RCM_PREFIX}/${script} ${script_alias}
else
    code ln -sf '  ' '..'/${RCM_PREFIX#${RCM_LIB}}/${script} ${script_alias}
    echo ln -sf '  ' '..'/${RCM_PREFIX#${RCM_LIB}}/${script} ${script_alias}
fi

# Wajib exit 0 jika success.
exit 0

